#include <stddef.h>

int highlight_all_matches(const int scores[], const int weights[], size_t length) {
    int total = 0;
    int weightTotal = 0;
    for (size_t index = 0; index < length; index++) {
        total += scores[index] * weights[index];
        weightTotal += weights[index];
    }
    return total / weightTotal;
}
